// Authored learning content. Unlisted syllabus topics remain visibly mapped, not falsely labelled complete.
const L = (course, title, spec) => ({...spec, course, title, status:"ready"});
export const lessons = [
  L("java","Structure and execution of a Java program",{
    question:"How does a text file become a running program?",
    opening:"Think of a recipe written in English. The recipe cannot cook dinner by itself: it must first be converted into instructions a kitchen can execute. Java uses a similar two-stage path, and that is why the same compiled program can run on different operating systems.",
    theory:[
      ["The pieces of a program","A Java source file normally contains a class declaration, braces delimiting the class body, and methods that describe behaviour. Execution begins at the `public static void main(String[] args)` entry point for a conventional command-line application. Statements end with semicolons. The name of a public top-level class must match its source filename. For example, `public class Hello` belongs in `Hello.java`."],
      ["Compilation is not execution","The Java compiler `javac Hello.java` checks syntax and converts the source into platform-independent bytecode stored in `Hello.class`. Running `java Hello` launches the Java Virtual Machine (JVM), which loads and verifies bytecode and executes it, typically using an interpreter and just-in-time compilation. The JDK contains developer tools including `javac`; the JVM runs bytecode. This division is the practical meaning of Java's portability."],
      ["Read errors by stage","A missing semicolon or unbalanced brace is a compile-time error. A division by zero may instead throw an exception while the program executes. A logically incorrect answer can occur even when compilation and execution both succeed. Identify the stage before trying to repair the problem."]
    ],diagram:"java",code:"public class Hello {\n    public static void main(String[] args) {\n        System.out.println(\"Hello, BCA!\");\n    }\n}",language:"java",worked:{task:"Predict the output, then identify the entry point.",steps:["Save the source as Hello.java.","Compile with javac Hello.java; this produces Hello.class.","Run java Hello; main prints one line."],answer:"Hello, BCA!"},industry:"Android and enterprise backend teams often choose languages running on the JVM. The important idea is the bytecode/runtime boundary—not a promise that every JVM feature works unchanged on every device.",quiz:[
      ["Which file is generated by javac Hello.java?",["Hello.exe","Hello.class","Hello.py","Hello.html"],1,"javac emits Java bytecode in a .class file."],
      ["What normally starts a command-line Java program?",["constructor","main method","package declaration","import statement"],1,"The JVM invokes the conventional main entry point."],
      ["Where is bytecode executed?",["web browser CSS engine","Java Virtual Machine","text editor","SQL server"],1,"The JVM loads and executes verified bytecode."],
      ["If a semicolon is missing, which stage usually reports it?",["compilation","printing","network transfer","garbage collection"],0,"Syntax is checked by the Java compiler."],
      ["A public class named Report belongs in which source file?",["Main.java","report.txt","Report.java","Report.class"],2,"The public class and source filename must match, including case."]
    ],exam:["State the purpose of the JVM.","Draw and explain the sequence from Java source to output, distinguishing JDK and JVM.","Write a small Java program, trace compilation and execution, and distinguish compile-time, runtime and logic errors with examples."]
  }),
  L("java","Classes, objects and members",{
    question:"How can one blueprint describe thousands of objects?",
    opening:"A banking app has many accounts, each with a balance and an owner. Writing a separate set of variables and functions for every account quickly becomes impossible. A class describes the common shape and behaviour, while each object holds its own state.",
    theory:[
      ["Blueprint versus instance","A class is a user-defined type that groups fields (data) and methods (operations). A `BankAccount` class might have a private balance field and public deposit method. `new BankAccount()` constructs an object. Two objects created from one class have separate instance fields: changing one account's balance need not affect the other. References such as `a` and `b` point to objects; they are not the objects themselves."],
      ["Encapsulation protects rules","If outside code could freely set the balance to a negative value, the account's rules would be easy to violate. Hiding fields with `private` and exposing controlled public methods is encapsulation. A constructor establishes an initial valid state; methods enforce changes. Static members belong to the class rather than an individual object. Instance methods can use `this` to refer to the current object."],
      ["Trace state, not just printouts","When studying object programs, draw each reference, each object, and its fields. Notice that assigning `b = a` makes both references point to the same object; it does not clone it. This detail explains many surprising results in Java interview and exam questions."]
    ],diagram:"object",code:"class Counter {\n    private int value = 0;\n    void increment() { value++; }\n    int read() { return value; }\n}\nclass Main {\n    public static void main(String[] args) {\n        Counter a = new Counter();\n        Counter b = a;\n        b.increment();\n        System.out.println(a.read());\n    }\n}",language:"java",worked:{task:"If b = a, what prints after b.increment()?",steps:["new creates one Counter object with value 0.","b = a copies the reference, not the object.","b.increment changes the single shared object to 1."],answer:"1"},industry:"E-commerce carts, user profiles and payment objects use the same modelling approach: a shared definition plus state held by individual instances.",quiz:[
      ["A class is primarily a...",["single object","blueprint for objects","database record","thread"],1,"Classes describe fields and behaviour."],
      ["Which keyword creates an ordinary object?",["static","class","new","private"],2,"new allocates and constructs an instance."],
      ["What does private protect?",["access to a member","memory size","package name","execution speed"],0,"Private access limits direct access from outside the class."],
      ["If b = a for object references, then...",["a is deleted","objects are cloned","both refer to the same object","b becomes null"],2,"Assignment copies a reference."],
      ["Which belongs to a particular instance?",["instance field","static constant","class declaration","package name"],0,"Instance fields hold per-object state."]
    ],exam:["Differentiate class and object.","Explain class members, constructor, encapsulation and the role of `this` with a diagram.","Design and implement a BankAccount class with valid deposits/withdrawals, explain state changes for multiple objects and justify visibility choices."]
  }),
  L("dbms","ER model: entities and sets",{
    question:"How do we turn a real college into a database design?",
    opening:"Before creating tables, an analyst must decide what the college actually needs to remember. Students take courses; instructors teach courses. These real-world things and their relationships can be drawn first, so mistakes are discovered before SQL is written.",
    theory:[
      ["Identify things and facts","An entity is an identifiable real-world object or concept, such as one student. An entity set is a collection of similar entities. Attributes describe them: Student may have StudentID, Name and Email. A key distinguishes individual records, while a domain restricts valid values, such as a date or positive integer. A relationship connects entities: Student ENROLLS_IN Course."],
      ["Cardinality is a business rule","A relationship is not complete until you understand how many instances can participate. In a college, one student can enroll in many courses and one course can contain many students, giving many-to-many cardinality. The enrollment may also have attributes such as Date and Grade. If one instructor heads exactly one department, that is a different cardinality rule. Participation constraints tell us whether an entity may exist without taking part."],
      ["From diagram to tables","An ER diagram is a conceptual model, not a physical database screenshot. When converting a many-to-many relationship to relational tables, we generally create an associative table such as Enrollment(StudentID, CourseID, Grade) with foreign keys to Student and Course. This separates student facts from enrollment facts and prevents repeated data."]
    ],diagram:"er",code:"CREATE TABLE Student (\n  StudentID INTEGER PRIMARY KEY,\n  Name VARCHAR(80) NOT NULL\n);\nCREATE TABLE Course (\n  CourseID INTEGER PRIMARY KEY,\n  Title VARCHAR(100) NOT NULL\n);\nCREATE TABLE Enrollment (\n  StudentID INTEGER REFERENCES Student(StudentID),\n  CourseID INTEGER REFERENCES Course(CourseID),\n  PRIMARY KEY (StudentID, CourseID)\n);",language:"sql",worked:{task:"Represent a student who enrolls in three courses.",steps:["Store the student once in Student.","Store each available course once in Course.","Insert three StudentID–CourseID pairs into Enrollment."],answer:"One Student row, three Course rows (if they are new), and three Enrollment rows."},industry:"University ERP systems, learning management platforms and ticket-booking systems all use relationship modelling before writing production schemas.",quiz:[
      ["Which is an entity set?",["one student named Asha","all students","a student's age","a plus sign"],1,"An entity set groups entities of one type."],
      ["StudentID is commonly a...",["relationship","domain","key attribute","diagram legend"],2,"A key uniquely identifies entities."],
      ["Many students take many courses: cardinality?",["1:1","1:N","M:N","zero only"],2,"Both sides may have multiple partners."],
      ["Enrollment Grade belongs most naturally to...",["Student only","Course only","the enrollment relationship","the university name"],2,"Grade describes a specific student-course relationship."],
      ["M:N mapping commonly needs...",["one free-text field","an associative table","no key","a separate database server"],1,"The bridge table stores each association."]
    ],exam:["Define entity and entity set.","Draw an ER model for Students, Courses and Enrollment, including cardinality and keys.","Design an ER model for a college registration system, convert it to relations, identify primary/foreign keys, and justify participation/cardinality assumptions."]
  }),
  L("dbms","Set operations and joins",{
    question:"How does an online shop connect an order to a customer's name?",
    opening:"A well-designed database does not copy the customer's name into every order. It stores a CustomerID in Orders and retrieves related facts when needed. A JOIN is how SQL combines those rows without losing the underlying separation.",
    theory:[
      ["Think in matching pairs","Suppose Customers has (1, Asha) and (2, Ravi), while Orders has (101, 1) and (102, 1). An INNER JOIN on Customers.id = Orders.customer_id returns two rows, both with Asha's name. Ravi has no matching order, so he does not appear. SQL joins operate on matching row combinations, not on how tables happen to be displayed on the screen."],
      ["Preserve unmatched rows when needed","A LEFT JOIN retains every row from the table on the left, filling unmatched right-side columns with NULL. That is helpful when asking which customers have never ordered. In a SELECT statement, moving a right-table filter from ON to WHERE can unexpectedly remove those unmatched customers: NULL does not pass ordinary equality tests. To find unmatched records, test `WHERE o.id IS NULL`."],
      ["Use aliases and clear keys","Qualify ambiguous column names (`c.id`, `o.id`) and join on the actual relationship. Joining only on an unrelated matching value can produce plausible-looking but wrong results. Without a join condition, a Cartesian product may grow rapidly. Start by verifying expected row counts on a tiny dataset before scaling a query."]
    ],diagram:"join",code:"SELECT c.name, o.order_id\nFROM Customers AS c\nLEFT JOIN Orders AS o\n  ON c.id = o.customer_id\nORDER BY c.name, o.order_id;",language:"sql",worked:{task:"Customers: Asha(1), Ravi(2). Orders: 101→1, 102→1. What does LEFT JOIN yield?",steps:["Asha matches order 101.","Asha also matches order 102.","Ravi is preserved even though no Order matches; its order_id is NULL."],answer:"(Asha,101), (Asha,102), (Ravi,NULL)."},industry:"Reporting dashboards, billing systems and product analytics frequently join normalized tables. Most inaccuracies come from the relationship and filtering rules, not from typing SQL keywords.",quiz:[
      ["INNER JOIN keeps...",["all left rows","only matching pairs","all unmatched rows","no rows"],1,"Only matching pairs survive an inner join."],
      ["LEFT JOIN without a match shows right-side values as...",["zero","empty text","NULL","false"],2,"Missing rows create NULL placeholders."],
      ["To find customers with no orders after LEFT JOIN, test...",["o.id IS NULL","o.id = 0","c.id IS NULL","COUNT(*) = -1"],0,"Unmatched right-side keys are NULL."],
      ["A join on an unrelated key may cause...",["better indexing","wrong matches","automatic normalization","a compile error every time"],1,"Syntactically valid SQL can still have wrong logic."],
      ["SQL aliases chiefly improve...",["column clarity","storage hardware","encryption keys","thread count"],0,"Aliases disambiguate referenced tables." ]
    ],exam:["State the purpose of INNER JOIN.","Compare INNER and LEFT JOIN using a two-table example with output.","Given Customer and Order schemas, write queries for all orders with customer names, customers without orders, and total orders per customer; explain NULL and row multiplication."]
  }),
  L("algorithms","Big-O, Omega and Theta notation",{
    question:"Why can a program feel fast on ten inputs and slow on a million?",
    opening:"Imagine searching a pile of cards. Looking at every card grows with the pile; splitting a sorted pile in half at each step grows much more slowly. Algorithm analysis describes how work scales as the input becomes large, independently of one laptop's clock speed.",
    theory:[
      ["Count operations before seconds","Running time is influenced by hardware, language and input. For an algorithm, we first count dominant elementary operations as a function T(n) of input size n. A loop that executes n times often performs work proportional to n, written Θ(n). Two nested loops each running n times typically do Θ(n²) work. Constants matter in practice but do not change the asymptotic growth class."],
      ["Upper, lower and tight bounds","O(g(n)) means an asymptotic upper bound: after some point the function grows no faster than a constant times g(n). Ω(g(n)) is a lower bound. Θ(g(n)) requires both bounds and describes a tight growth rate. These are mathematical bounds, not synonyms for worst, best and average cases. Each case can separately have an O, Ω or Θ bound."],
      ["Compare at a useful scale","If T(n) = 3n² + 10n + 7, the quadratic term eventually dominates, so T(n) is Θ(n²). A binary search on a sorted array halves the remaining search space, requiring about log₂(n) comparisons. On one million elements that is around 20 decisions, provided sorted input and efficient indexing."]
    ],diagram:"complexity",code:"function linearSearch(items, target) {\n  for (let i = 0; i < items.length; i++) {\n    if (items[i] === target) return i;\n  }\n  return -1;\n}",language:"javascript",worked:{task:"Find the tight bound for 5n² + 2n + 100.",steps:["Identify terms: quadratic, linear, constant.","For sufficiently large n, n² dominates n and 1.","Positive constant factors do not change Θ class."],answer:"Θ(n²)"},industry:"Search engines, route planners and database engineers choose algorithms by expected scale. A few milliseconds saved per operation becomes substantial when the operation runs millions of times.",quiz:[
      ["Which grows fastest asymptotically?",["log n","n","n log n","n²"],3,"Quadratic growth eventually exceeds the others."],
      ["Θ denotes...",["only best case","tight asymptotic bound","actual milliseconds","memory only"],1,"Both upper and lower asymptotic bounds hold."],
      ["7n + 20 is Θ...",["1","log n","n","n²"],2,"Linear term dominates the constant."],
      ["Binary search assumes...",["random input","sorted sequence","linked list only","all values unique"],1,"It relies on sorted order to eliminate half each step."],
      ["Big-O is a statement about...",["one benchmark only","asymptotic upper growth","CPU brand","source file size"],1,"Big-O gives an eventual upper bound."]
    ],exam:["Define O and Ω notations.","Explain O, Ω and Θ with a graph and classify three sample functions.","Derive asymptotic running times for a single loop, nested loop and binary search; discuss worst versus average input cases and assumptions."]
  }),
  L("algorithms","Breadth-first search",{
    question:"How does a map discover the fewest roads to a destination?",
    opening:"Suppose each road counts as one step. Exploring every possible long route is unnecessary: first check places one road away, then two roads away, then three. This layer-by-layer exploration is breadth-first search (BFS).",
    theory:[
      ["The queue creates layers","BFS begins at a start vertex, marks it visited, and places it in a first-in-first-out queue. Repeatedly remove the front vertex and enqueue its unvisited neighbours. Because earlier vertices leave first, every vertex discovered at distance d is processed before vertices at distance d+1. Store a parent when discovering a vertex to reconstruct a path."],
      ["Shortest paths in unweighted graphs","In an unweighted graph, BFS finds a path with the minimum number of edges from the start to each reachable vertex. This does not mean the cheapest path when edges have different travel costs; Dijkstra's algorithm handles nonnegative weighted edges. For a graph with V vertices and E edges stored as adjacency lists, BFS visits each vertex and examines each edge a constant number of times, giving O(V + E) time."],
      ["Avoid duplicate work","Mark a vertex as visited when enqueuing it, not only after removing it. Otherwise two neighbours may queue the same vertex repeatedly. For directed graphs, only follow outgoing edges unless the problem explicitly treats them as bidirectional. The neighbour order can change the traversal order, but not the minimum edge distance."]
    ],diagram:"bfs",code:"from collections import deque\n\ndef bfs(graph, start):\n    visited = {start}\n    queue = deque([start])\n    order = []\n    while queue:\n        node = queue.popleft()\n        order.append(node)\n        for nxt in graph[node]:\n            if nxt not in visited:\n                visited.add(nxt)\n                queue.append(nxt)\n    return order",language:"python",worked:{task:"Graph: A→B,C; B→D; C→E. Trace BFS from A (alphabetical neighbours).",steps:["Queue [A]. Visit A, enqueue B,C.","Visit B, enqueue D. Visit C, enqueue E.","Visit D then E; queue becomes empty."],answer:"A, B, C, D, E"},industry:"Social-network degrees of separation, nearest transformations and unweighted navigation use BFS. It is also a foundation for web crawling and AI state-space search.",quiz:[
      ["BFS uses a...",["stack","queue","heap only","recursion only"],1,"FIFO order processes earlier discovered vertices first."],
      ["In an unweighted graph, BFS finds...",["maximum-cost path","minimum edge count","minimum-weight tree always","all Hamiltonian paths"],1,"BFS minimizes the number of edges."],
      ["With adjacency lists BFS costs...",["O(V+E)","O(VE²)","O(1)","O(2^V)"],0,"Each vertex and edge is examined a bounded number of times."],
      ["When should a vertex be marked visited?",["when queued","only at the end","never","after every edge"],0,"Marking on discovery prevents duplicate queueing."],
      ["Weighted shortest paths with nonnegative weights generally use...",["BFS always","Dijkstra","Bubble sort","DFS only"],1,"Dijkstra accounts for varying edge weights."]
    ],exam:["State the data structure used by BFS.","Write BFS pseudocode and trace a five-vertex graph with queue states.","Prove why BFS gives a shortest edge-count path in an unweighted graph; analyze time/space and contrast DFS and Dijkstra."]
  }),
  L("python","for, while, range, break and continue",{
    question:"How do apps repeat work without copying the same code?",
    opening:"A shop must total hundreds of bill items. One statement per item would be fragile. A loop expresses the repeated operation once, while its controlling condition decides when to stop.",
    theory:[
      ["Choose the loop by the question","Use `for` to iterate across an iterable such as a list or `range(5)`, which produces 0, 1, 2, 3, 4. Use `while` when repetition continues as long as a Boolean condition stays true—for example, while a correct password has not been entered. Indentation, not braces, determines the loop body in Python."],
      ["Trace updates and termination","A while loop must usually change something used by its condition. Otherwise it risks running forever. For a loop summing numbers 1 through 4, start `total = 0` and add each number: 1, 3, 6, 10. Trace the variables after each iteration. The last argument in `range(start, stop, step)` is a step, and stop is exclusive; forgetting that exclusion is a common off-by-one error."],
      ["Two distinct jump statements","`break` immediately exits the nearest loop. `continue` skips the rest of the current iteration and proceeds to the next one. These are useful for early stopping and filtering, but an unnecessarily complicated mix of jumps makes reasoning harder. A nested loop repeats the inner loop for each outer iteration; this often matters both for output patterns and time complexity."]
    ],diagram:"loop",code:"total = 0\nfor number in range(1, 5):\n    total += number\nprint(total)",language:"python",worked:{task:"Trace range(1,5) and total.",steps:["Iterate over 1,2,3,4 (5 is excluded).","Update total as 1,3,6,10.","After the loop, print total."],answer:"10"},industry:"Loops process uploaded CSV rows, monthly financial records, log files and search results. At large scale, developers also assess whether repeated work should be vectorized or batched.",quiz:[
      ["range(3) yields...",["1,2,3","0,1,2","0,1,2,3","3 only"],1,"The stop bound is exclusive."],
      ["Which repeats while a condition is true?",["class","while","import","return"],1,"while checks its condition before each iteration."],
      ["break affects...",["current function always","nearest loop","all running programs","only the next statement"],1,"break exits the nearest enclosing loop."],
      ["continue means...",["stop program","skip to next iteration","restart interpreter","print result"],1,"It skips the remainder of the current iteration."],
      ["Why can while True with no break be risky?",["it cannot compile","it may never terminate","it always stops at 10","it deletes variables"],1,"There may be no termination path."]
    ],exam:["Differentiate break and continue.","Trace a Python for-loop and while-loop for the same summation, including range boundaries.","Write a menu-driven Python program using loops and conditions, analyze termination, and trace nested-loop output for a given pattern."]
  }),
  L("python","Defining and calling functions",{
    question:"Why put repeated logic inside a function?",
    opening:"If billing, reports and checkout all calculate the same tax rule, copying three formulas creates three chances to introduce bugs. A function gives one well-named operation an interface, inputs and a result.",
    theory:[
      ["Define an interface","A Python function begins with `def`, a name, parameters in parentheses, a colon and an indented body. Calling the function transfers values into local parameter names. The `return` statement sends a value back to the caller; printing is not the same as returning. If a function reaches the end without a return expression, it returns `None`."],
      ["Arguments and defaults","Positional arguments map by order. Keyword arguments map by parameter name. A default parameter makes one argument optional. Place parameters with defaults after required parameters in normal definitions. Keep defaults immutable when possible: a mutable list as a default is created once at definition time and can unexpectedly be shared between calls."],
      ["Scope and testability","Variables assigned inside a function are normally local. A function can take a numeric value and return a numeric result without reading global state; this makes behaviour easy to test. For example, `area(3,4)` should reliably return 12. As programs grow, splitting data preparation, calculation and display into functions makes each responsibility clearer and encourages reuse."]
    ],diagram:"function",code:"def area(length, width=1):\n    if length < 0 or width < 0:\n        raise ValueError('Dimensions cannot be negative')\n    return length * width\n\nprint(area(3, 4))\nprint(area(5))",language:"python",worked:{task:"What is the difference between area(3,4) and area(5)?",steps:["First call binds length=3 and width=4, returning 12.","Second call uses default width=1, returning 5.","print displays values returned by each call."],answer:"Two lines: 12 and 5"},industry:"In payroll, invoicing and web APIs, small tested functions isolate business calculations and reduce errors when a rule changes.",quiz:[
      ["Function definitions start with...",["function","def","proc","let"],1,"Python uses the def keyword before a function name and parameters."],
      ["Without explicit return, Python returns...",["0","false","None","error always"],2,"A function returns None implicitly."],
      ["A keyword argument is matched by...",["its name","memory address","file name","only position"],0,"Keyword binding names the parameter."],
      ["Local variables generally belong to...",["the module only","the function scope","every object","the compiler cache"],1,"Assignments inside a function establish local names by default."],
      ["What is risky as a default value?",["an integer","None","a mutable list","a string"],2,"Mutable defaults are reused across calls."]
    ],exam:["Define a function and a parameter.","Explain positional, keyword and default arguments with outputs.","Design functions for an invoice calculator; explain return values, local scope, validation and tests for normal and invalid inputs."]
  }),
  L("ai","Greedy best-first and A* search",{
    question:"How does a navigation app balance distance already travelled with distance remaining?",
    opening:"When finding a route, one tempting idea is to move towards the destination as fast as possible. But a road heading directly toward the goal may dead-end. A* combines what it has already spent with an estimate of what remains.",
    theory:[
      ["States, costs and estimates","Search begins with an initial state, a goal test and actions that move between states. `g(n)` is the known cheapest cost from start to node n so far. `h(n)` estimates remaining cost to the goal. Greedy best-first search prioritizes `h(n)` alone. A* prioritizes `f(n) = g(n) + h(n)`, balancing travel so far with estimated travel remaining."],
      ["Why the heuristic matters","If h never overestimates the true remaining cost, it is admissible. Under appropriate graph-search conditions, including consistent h or suitable node reopening, A* can find an optimal solution for nonnegative edge costs. Setting h=0 reduces A* to uniform-cost search. A heuristic that aggressively overestimates may explore fewer nodes but can lose optimality."],
      ["Trace the frontier","Maintain a priority queue of frontier states ordered by f. When exploring a node, consider neighbours and update their best known g and parent when finding a cheaper route. Terminate when the goal is removed from the frontier under the algorithm's optimality conditions. Draw a small graph with g, h and f values; then compare the order of selection with greedy search."]
    ],diagram:"astar",code:"from heapq import heappush, heappop\n# Frontier entries are ordered by estimated total cost f = g + h.\nfrontier = []\nheappush(frontier, (0, 'Start'))\nwhile frontier:\n    score, node = heappop(frontier)\n    print('Expand:', node, 'priority:', score)\n    break  # Replace with a full graph search for a real solution.",language:"python",worked:{task:"Two frontier nodes: A with g=5,h=2; B with g=2,h=6. Which does A* choose?",steps:["Compute f(A)=5+2=7.","Compute f(B)=2+6=8.","Choose the lower estimated total cost."],answer:"A (f=7), assuming neither is stale."},industry:"Route planning, robot motion and puzzle-solving use search heuristics. In production, graph size, admissibility and changing travel costs all affect the chosen algorithm.",quiz:[
      ["A* prioritizes...",["g only","h only","g+h","degree only"],2,"A* combines known and estimated remaining costs."],
      ["Greedy best-first prioritizes...",["h","g+h","g","queue order"],0,"Greedy chooses the node estimated closest to goal."],
      ["Admissible heuristic...",["always overestimates","never overestimates true remaining cost","is negative everywhere","ignores goal"],1,"It is an optimistic lower bound."],
      ["A* with h=0 behaves like...",["BFS on all weighted graphs","uniform-cost search","DFS","hill climbing"],1,"With zero heuristic, f(n) equals the path cost g(n), so the smallest known cost is expanded."],
      ["For A g=4,h=3, f is...",["1","4","7","12"],2,"A* adds known path cost and estimated remaining cost: 4 + 3 = 7."]
    ],exam:["Write the A* evaluation function.","Compare greedy best-first and A* on a weighted example.","Trace A* with a provided heuristic table, show open/closed states and discuss admissibility, consistency and optimality."]
  }),
  L("networks","OSI layers",{
    question:"What happens between pressing Send and a message arriving?",
    opening:"A message travels through software, network devices, physical signals and back into software. Dividing these tasks into layers makes failures easier to locate and lets different technologies work together.",
    theory:[
      ["Seven responsibilities","The OSI reference model has seven layers: Physical (signals and bits), Data Link (frames and local delivery), Network (packets and routing), Transport (end-to-end segmentation and reliability), Session (dialogue management), Presentation (data format and translation) and Application (network services for programs). The model describes responsibilities; real Internet protocols do not necessarily implement every OSI layer as a distinct module."],
      ["Encapsulation in motion","When sending, each lower layer adds control information appropriate to its job; this is encapsulation. A typical web request passes from HTTP to TCP to IP to link-layer frames and physical signals. On receipt, layers remove the relevant headers and deliver the content upwards. A router mostly makes forwarding decisions using network-layer addresses, while an Ethernet switch primarily uses link-layer addresses."],
      ["Use layers to troubleshoot","If the cable is disconnected, begin at Physical. If two local devices cannot exchange frames, inspect Data Link. If packets cannot reach another network, investigate IP routing. If a webpage name does not resolve, inspect DNS (application-layer service). The seven-layer OSI model is a conceptual framework; the more widely deployed TCP/IP suite is commonly described in fewer layers."]
    ],diagram:"osi",code:"# Example layered path (conceptual, not executable)\nHTTP request → TCP segment → IP packet → Ethernet frame → bits\n# Receiver processes those encapsulations in reverse.",language:"text",worked:{task:"A laptop can reach the router IP but cannot open a website by hostname. Where might you check first?",steps:["Local physical and link communication appear to work.","IP connectivity to router is established, but Internet reachability is not yet proven.","Check DNS resolution, then broader routing/connectivity if needed."],answer:"DNS/application-layer name resolution is one possible cause; diagnose rather than assuming."},industry:"Network support teams use layered reasoning for Wi-Fi issues, cloud outages, VPN failures and application latency. It shortens troubleshooting by eliminating layers known to work.",quiz:[
      ["How many layers are in the OSI model?",["4","5","6","7"],3,"OSI defines seven reference layers."],
      ["Which handles routing packets?",["Physical","Data Link","Network","Presentation"],2,"Network layer selects routes between networks."],
      ["Ethernet frames are associated mainly with...",["Data Link","Session","Application","Presentation"],0,"Framing and local link addressing are layer 2 tasks."],
      ["Which is an application-layer service?",["DNS","optical fibre","voltage level","MAC header"],0,"DNS provides name resolution."],
      ["Encapsulation means...",["removing all addresses","adding protocol information around data","encryption only","compressing all files"],1,"Each layer wraps information for its responsibility."]
    ],exam:["List all seven OSI layers.","Draw the OSI stack and explain each layer with a practical protocol/device example.","Trace a browser request across protocol layers and compare OSI to TCP/IP; diagnose physical, link, network and application faults."]
  }),
  L("iot","Sensors and their properties",{
    question:"How does a smart greenhouse know when to water plants?",
    opening:"A system cannot act on the soil condition unless it measures something first. A soil-moisture sensor translates a physical property into a signal that a controller can read. Correct measurement is harder than simply connecting two wires.",
    theory:[
      ["Sensor versus actuator","A sensor converts a physical quantity (temperature, light, pressure, moisture) into useful information. An actuator changes the environment: a valve opens, a motor moves or a heater turns on. In a control loop, a controller reads the sensor, compares the value with a rule, and commands an actuator. This separates observation from action."],
      ["Quality of measurements","Resolution is the smallest change the measurement system can distinguish; accuracy is closeness to the true value, and precision is repeatability. A sensor can be precise but systematically wrong. Range, calibration, noise, sampling interval and environmental conditions affect measurements. A controller should account for sensor failure instead of interpreting every reading as valid."],
      ["Avoid oscillation","A simplistic rule that turns a pump on below 30% moisture and off at 30% can switch rapidly near the boundary. Hysteresis creates two thresholds: turn on below 28% and turn off above 35%. This stabilizes behaviour. Safety limits and manual override are important when IoT systems operate physical equipment."]
    ],diagram:"iot",code:"const dryThreshold = 28;\nconst wetThreshold = 35;\nlet pumpOn = false;\nfunction control(moisture) {\n  if (!pumpOn && moisture < dryThreshold) pumpOn = true;\n  else if (pumpOn && moisture > wetThreshold) pumpOn = false;\n  return pumpOn;\n}",language:"javascript",worked:{task:"Start with pump OFF. Readings: 27%, 32%, 36%. Trace the output.",steps:["27 is below 28: pump turns ON.","32 is between thresholds: pump stays ON.","36 exceeds 35: pump turns OFF."],answer:"ON → ON → OFF"},industry:"Smart agriculture, cold-chain monitoring and industrial automation combine calibrated sensing, software decisions and actuators. Reliable systems also record readings for later diagnosis.",quiz:[
      ["A sensor primarily...",["moves a motor","measures a physical property","stores a password","compiles Java"],1,"A sensor converts physical phenomena into information."],
      ["An actuator might be a...",["temperature reading","water valve","database table","sample interval"],1,"Valves perform physical actions."],
      ["Resolution is...",["smallest distinguishable change","maximum error always","network speed","number of buttons"],0,"Resolution concerns the detail a measurement can represent."],
      ["Hysteresis uses...",["one threshold always","two switching thresholds","no sensors","random output"],1,"Different on/off thresholds avoid rapid toggling."],
      ["A precise sensor can still be...",["inaccurate","nonphysical","always perfect","a database"],0,"Repeatability and accuracy are different properties."]
    ],exam:["Differentiate sensor and actuator.","Explain resolution, accuracy, range, precision and calibration with examples.","Design a greenhouse control loop, draw its diagram, select sensors/actuators and trace a safe hysteresis control algorithm."]
  }),
  L("cloud","Virtualization foundations",{
    question:"How can one physical computer behave like several computers?",
    opening:"A company buys a powerful server but uses only a small fraction of its CPU most of the day. Virtualization divides its capacity into independently managed virtual machines, each appearing to run its own operating system.",
    theory:[
      ["Hypervisor and guest","A hypervisor provides virtual hardware—processor time, memory, disks and network interfaces—to guest virtual machines. Type 1 hypervisors run directly on the host hardware; Type 2 run on a conventional host operating system. Multiple VMs can share a host while maintaining isolation boundaries. The virtual machines are not free: scheduling and memory overhead still exist."],
      ["Virtual machines versus containers","A VM includes a guest operating system kernel. A typical container isolates processes while sharing its host kernel. Containers often start faster and use fewer resources, but isolation and compatibility trade-offs differ. A cloud provider may use virtualization underneath container services; these approaches complement rather than replace each other."],
      ["Why cloud uses it","Virtualization enables resource pooling, rapid provisioning, snapshots and migration. It helps providers allocate capacity across customers and lets businesses scale workloads as demand changes. Availability also requires monitoring, backups and redundancy: running multiple VMs on one physical machine does not protect against that machine failing."]
    ],diagram:"cloud",code:"Physical host\n  └─ Hypervisor\n       ├─ VM A (guest OS + app)\n       ├─ VM B (guest OS + app)\n       └─ VM C (guest OS + app)",language:"text",worked:{task:"A 32 GB host reserves 4 GB for host overhead. How many 7 GB VMs fit without overcommit?",steps:["Usable memory = 32 − 4 = 28 GB.","Each VM is allocated 7 GB.","28 ÷ 7 = 4 VMs; other resource limits may reduce this."],answer:"At most 4 by this memory calculation."},industry:"Cloud service providers use virtualization and orchestration to turn data-centre hardware into flexible compute products. The economics depend on safe sharing and reliable operations.",quiz:[
      ["A hypervisor manages...",["virtual machines","printed documents","DNS names only","SQL columns"],0,"The hypervisor mediates virtual hardware resources."],
      ["A Type 1 hypervisor runs...",["on host hardware","inside a browser only","as a spreadsheet","on a web page"],0,"Bare-metal hypervisors run directly on hardware."],
      ["A conventional VM usually contains...",["a guest OS","only JavaScript","no memory","a printer driver only"],0,"VMs virtualize a whole machine environment."],
      ["Containers typically share...",["host kernel","each other's passwords","all disks publicly","no operating system features"],0,"Container isolation commonly shares the host kernel."],
      ["Four VMs on one host guarantee fault tolerance?",["yes","no","only on weekends","only for SQL"],1,"A single host can be a shared failure point."]
    ],exam:["Define virtualization.","Compare Type 1/Type 2 hypervisors, VMs and containers with diagrams.","Design a small virtualized deployment and discuss isolation, resource allocation, elasticity, availability and single-host failure."]
  }),
  L("datascience","Apriori algorithm",{
    question:"Which products are often bought together?",
    opening:"Supermarkets analyze shopping baskets to discover patterns such as tea and biscuits appearing together. The Apriori algorithm systematically searches for frequently co-occurring items without checking every possible large set first.",
    theory:[
      ["Support as a count of baskets","An itemset is any combination of products. Its support is the fraction of transactions containing all its items. If bread appears in three of four transactions, its support is 3/4 = 75%. A frequent itemset meets a minimum support threshold chosen by the analyst. Support is not the same as a causal relationship or evidence that buying one product causes another purchase."],
      ["The Apriori property","Every non-empty subset of a frequent itemset must also be frequent. Thus, if {bread, milk} occurs often, both bread and milk must individually occur at least that often. Conversely, if {milk, eggs} is infrequent, there is no reason to count any larger set containing both. Apriori uses this pruning rule to reduce the search space."],
      ["Rules need care","From frequent itemsets, an association rule such as bread → milk can be described using confidence = support(bread ∪ milk) / support(bread). Lift compares rule confidence with the baseline frequency of milk. High confidence alone may simply reflect that milk is bought by nearly everyone. Interpretation requires base rates, representative transactions and domain judgment."]
    ],diagram:"apriori",code:"baskets = [\n  {'bread','milk'},\n  {'bread','eggs'},\n  {'bread','milk','eggs'},\n  {'milk','eggs'}\n]\nsupport = sum({'bread','milk'} <= b for b in baskets) / len(baskets)\nprint(support)",language:"python",worked:{task:"For the four baskets above, compute support({bread,milk}).",steps:["Basket 1 contains both.","Basket 3 also contains both.","Support = 2 ÷ 4 = 0.5 (50%)."],answer:"50%"},industry:"Retail affinity analysis, recommendation systems and process-log analysis use frequent patterns, but analysts should protect privacy and avoid mistaking correlation for causation.",quiz:[
      ["Support measures...",["fraction of containing transactions","price of product","processing speed","number of shops"],0,"Support is transaction frequency."],
      ["Apriori prunes a superset when its subset is...",["frequent","infrequent","empty","sorted"],1,"An infrequent subset makes every containing superset infrequent."],
      ["2 out of 8 baskets gives support...",["10%","20%","25%","50%"],2,"Support is containing baskets divided by all baskets: 2/8 = 0.25 or 25%."],
      ["Confidence(A→B) is...",["support(A∪B)/support(A)","support(A)/support(B)","support(B) only","1-support(A)"],0,"Confidence is conditional itemset frequency."],
      ["High confidence proves causation?",["always","never by itself","only with SQL","only at 100%"],1,"Association is not proof of cause." ]
    ],exam:["Define frequent itemset.","Explain support, confidence and Apriori pruning with an example.","Perform Apriori on a small transaction dataset, form one association rule and evaluate support, confidence, lift and potential business limitations."]
  }),
  L("ml","Accuracy, precision and recall",{
    question:"Why can a classifier be 99% accurate but still miss every dangerous case?",
    opening:"Imagine a screening dataset where only 1% of cases are positive. A model that predicts negative for everyone has 99% accuracy, yet finds no positives. Accuracy alone hides that failure.",
    theory:[
      ["Begin with the confusion matrix","For a binary classifier, true positives (TP) correctly predict positive, false positives (FP) incorrectly raise an alarm, false negatives (FN) miss positives and true negatives (TN) correctly reject negatives. Accuracy is (TP+TN)/(TP+FP+FN+TN). Precision is TP/(TP+FP): of all predicted positives, how many were correct? Recall or sensitivity is TP/(TP+FN): of all actual positives, how many did we find?"],
      ["Match metrics to consequences","High precision matters when false alarms are costly, for example when alerts require expensive manual review. High recall matters when missing a positive has high consequence. Specificity is TN/(TN+FP), the fraction of actual negatives correctly rejected. F1 combines precision and recall via their harmonic mean; it ignores true negatives, so it is not a universal replacement for accuracy."],
      ["Thresholds change trade-offs","Many classifiers output a score and apply a threshold to decide positive versus negative. Moving the threshold changes TP, FP, TN and FN. A ROC curve plots true-positive rate against false-positive rate across thresholds; AUC summarizes discrimination across them. Always examine class prevalence and a confusion matrix alongside a single score."]
    ],diagram:"matrix",code:"tp, fp, fn, tn = 18, 2, 6, 74\nprecision = tp / (tp + fp)\nrecall = tp / (tp + fn)\naccuracy = (tp + tn) / (tp + fp + fn + tn)\nprint(precision, recall, accuracy)",language:"python",worked:{task:"Compute metrics for TP=18, FP=2, FN=6, TN=74.",steps:["Precision = 18/20 = 0.90.","Recall = 18/24 = 0.75.","Accuracy = 92/100 = 0.92."],answer:"Precision 90%, recall 75%, accuracy 92%."},industry:"Fraud monitoring, quality control and medical research evaluate false alarms and misses differently. A system needs domain-defined error costs and human review before deployment.",quiz:[
      ["Precision denominator is...",["TP+FP","TP+FN","TN+FP","TP+TN"],0,"Precision examines all predicted positives."],
      ["Recall denominator is...",["TP+FP","TP+FN","TN+FP","TN+FN"],1,"Recall examines all actual positives."],
      ["A false negative is...",["negative correctly predicted","positive predicted negative","negative predicted positive","positive correctly predicted"],1,"The system missed an actual positive."],
      ["Specificity uses...",["TN/(TN+FP)","TP/(TP+FN)","TP/(TP+FP)","FP/(TP+FP)"],0,"Specificity measures correct rejections."],
      ["Can accuracy hide poor minority-class performance?",["yes","no","only in regression","only with perfect data"],0,"Imbalanced classes can inflate accuracy."]
    ],exam:["Define false positive and false negative.","Draw a confusion matrix and compute precision, recall, specificity and accuracy.","Evaluate a classifier under class imbalance; compare decision thresholds and justify suitable metrics for a high-cost false-negative scenario."]
  })
];

